"use client";

import { FormEvent, useCallback, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { io } from "socket.io-client";
import { getApiBase } from "../lib/api";
import { teamDisplayCode, teamDisplayName } from "../lib/team-labels";

const api=getApiBase();
type Team={id:string;teamCode:string;name:string;active:boolean;credits:number;reservedCredits:number;users:{id:string;email:string;teamSlot:number}[];score?:{total:number}|null};
type Card={id:string;name:string;description:string;imageUrl:string|null;benefits:string[];conditions:string|null;usageLimit:number|null;startingBid:number;published:boolean;version:number;effectType:string;effectValue:number;successor?:{id:string}|null};
type Problem={id:string;problemCode:string;title:string;difficulty:string;statement:string;inputFormat:string;outputFormat:string;constraints:string;sampleExamples:{input:string;output:string;explanation?:string}[];startingBid:number;maxBid:number|null;maxScore:number;maxTimingPoints:number;published:boolean;version:number;timeLimitSeconds:number;testCases:{id:string;input:string;expected:string;position:number;isSample:boolean;weight:number}[];successor?:{id:string}|null};
type Auction={id:string;kind:string;status:string;endsAt:string|null;items:{id:string;status:string;currentBid:number;highestTeam?:{teamCode:string;name:string}|null;card?:{name:string}|null;problem?:{problemCode:string;title:string}|null}[]};
type EventState={id:string;name:string;status:string;codingRoundOpen:boolean;leaderboardVisibility:string};
type TeamCredential={teamCode:string;teamSlot:number;email:string;password:string};
type Tab="overview"|"teams"|"cards"|"problems"|"auctions"|"scores"|"event";
type AdminConfirmation={title:string;message:string;confirmLabel:string;action:()=>Promise<unknown>;destructive?:boolean};
type ConfirmAdminAction=(title:string,message:string,confirmLabel:string,action:()=>Promise<unknown>,destructive?:boolean)=>void;

export default function AdminPage(){
 const router=useRouter();const [tab,setTab]=useState<Tab>("overview");const [teams,setTeams]=useState<Team[]>([]);const [onlineMembers,setOnlineMembers]=useState<Record<string,string[]>>({});const [cards,setCards]=useState<Card[]>([]);const [problems,setProblems]=useState<Problem[]>([]);const [displayCardId,setDisplayCardId]=useState<string|null>(null);const [displayProblemId,setDisplayProblemId]=useState<string|null>(null);const [editingCard,setEditingCard]=useState<Card|null>(null);const [editingProblem,setEditingProblem]=useState<Problem|null>(null);const [auctions,setAuctions]=useState<Auction[]>([]);const [event,setEvent]=useState<EventState|null>(null);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [message,setMessage]=useState("");const [confirmation,setConfirmation]=useState<AdminConfirmation|null>(null);const [confirmationBusy,setConfirmationBusy]=useState(false);const [teamCredentials,setTeamCredentials]=useState<TeamCredential[]|null>(null);
 const load=useCallback(async()=>{
  const session=await fetch(`${api}/api/auth/session`,{credentials:"include"});if(!session.ok){router.replace("/");return;}const identity=(await session.json()).user;if(identity.role!=="ADMIN"){router.replace("/dashboard");return;}
  const paths=["/api/admin/teams","/api/admin/power-cards","/api/admin/problems","/api/admin/event","/api/admin/auctions","/api/admin/display"];
  const responses=await Promise.all(paths.map(path=>fetch(`${api}${path}`,{credentials:"include"})));
  if(responses.some(r=>r.status===401)){router.replace("/");return;}
  const [t,c,p,e,a,d]=await Promise.all(responses.map(r=>r.json()));
  setTeams(t.teams??[]);setCards(c.cards??[]);setProblems(p.problems??[]);setEvent(e.event??null);setAuctions(a.auctions??[]);setDisplayCardId(d.displayCardId??null);setDisplayProblemId(d.displayProblemId??null);setLoading(false);
 },[router]);
 useEffect(()=>{load().catch(e=>{setMessage(e.message);setLoading(false);});},[load]);
 useEffect(()=>{const socket=io(api,{withCredentials:true,transports:["websocket"]});socket.on("team.presence.snapshot",(snapshot:{teamId:string;connectedMembers:string[]}[])=>setOnlineMembers(Object.fromEntries(snapshot.map(item=>[item.teamId,item.connectedMembers]))));socket.on("team.presence",(presence:{teamId:string;connectedMembers:string[]})=>setOnlineMembers(current=>({...current,[presence.teamId]:presence.connectedMembers})));socket.on("team.updated",()=>void load());socket.on("auction.updated",()=>void load());socket.on("submission.updated",()=>void load());socket.on("event.updated",()=>void load());return()=>{socket.disconnect();};},[load]);
  async function request(path:string,method="POST",body?:unknown,notify=true){setBusy(true);setMessage("");try{const response=await fetch(`${api}${path}`,{method,credentials:"include",headers:body?{"Content-Type":"application/json"}:{},body:body?JSON.stringify(body):undefined});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error??"Request failed");await load();if(notify)setMessage(data.reset?"Scoreboard reset. Every team is at zero, score adjustment history is cleared, and the coding round is closed.":data.creditBonusAwarded?`Credit bonus updated for ${data.teamCount} teams: ${data.totalBonus} points in total.`:"Changes saved.");return data;}catch(e){setMessage(e instanceof Error?e.message:"Request failed");return null;}finally{setBusy(false);}}
 function askConfirmation(title:string,message:string,confirmLabel:string,action:()=>Promise<unknown>,destructive=false){setConfirmation({title,message,confirmLabel,action,destructive});}
 async function confirmAction(){if(!confirmation)return;setConfirmationBusy(true);try{await confirmation.action();}catch(error){setMessage(error instanceof Error?error.message:"Action failed");}finally{setConfirmation(null);setConfirmationBusy(false);}}
 async function logout(){await fetch(`${api}/api/auth/logout`,{method:"POST",credentials:"include"});router.replace("/");}
 if(loading)return <main className="workspace-loading"><div className="loading-mark">A</div><p>LOADING EVENT CONTROL…</p></main>;
 return <main className="admin-shell"><aside className="admin-sidebar"><a className="brand" href="/admin"><span className="brand-mark">A</span><span>ALGORITHM<br/><b>AUCTION</b></span></a><div className="admin-label">EVENT MANAGEMENT</div><nav>{([ ["overview","◫","Overview"],["teams","♙","Teams management"],["cards","◇","Power cards"],["problems","⌘","Algorithms"],["auctions","↗","Auctions"],["scores","#","Score management"],["event","◷","Event controls"]] as [Tab,string,string][]).map(([id,icon,label])=><button key={id} className={tab===id?"selected":""} onClick={()=>setTab(id)}><span>{icon}</span>{label}</button>)}</nav><div className="sidebar-bottom"><span className="admin-presence"><i/> ADMIN SESSION</span><button className="sidebar-exit" onClick={logout}>SIGN OUT ↗</button></div></aside>
 <section className="admin-main"><header className="admin-topbar"><div><small>ALGORITHM AUCTION <span>/</span> CONTROL ROOM</small><h1>{tabLabel(tab)}</h1></div><div className="admin-top-right"><span className="admin-event-chip"><i/>{event?.status??"DRAFT"}</span><a href="/leaderboard">LIVE LEADERBOARD ↗</a></div></header>
 {message&&<div className="confirm-modal-backdrop notice-backdrop"><section className="confirm-modal" role="dialog" aria-modal="true" aria-labelledby="admin-notice-title"><span className="section-index">ADMIN MESSAGE</span><h2 id="admin-notice-title">{message==="Changes saved."?"Completed":"Please note"}</h2><p>{message}</p><div className="confirm-modal-actions"><button type="button" className="outline-action" onClick={()=>setMessage("")}>CLOSE</button></div></section></div>}
 {confirmation&&<div className="confirm-modal-backdrop"><section className="confirm-modal" role="alertdialog" aria-modal="true" aria-labelledby="admin-confirm-title"><span className="section-index">CONFIRM ADMIN ACTION</span><h2 id="admin-confirm-title">{confirmation.title}</h2><p>{confirmation.message}</p><div className="confirm-modal-actions"><button type="button" className={confirmation.destructive?"danger-action":"primary-button compact"} onClick={()=>void confirmAction()} disabled={confirmationBusy}>{confirmationBusy?"PLEASE WAIT…":confirmation.confirmLabel}</button><button type="button" className="outline-action" onClick={()=>setConfirmation(null)} disabled={confirmationBusy}>CLOSE</button></div></section></div>}
 {teamCredentials&&<div className="confirm-modal-backdrop"><section className="confirm-modal credential-modal" role="dialog" aria-modal="true" aria-labelledby="team-credentials-title"><span className="section-index">NEW TEAM LOGINS</span><h2 id="team-credentials-title">Share these credentials with the teams.</h2><p>Each team member must sign in with the email and password shown. Existing team sessions were signed out. Administrator logins were not changed.</p><pre>{teamCredentials.map((credential)=>`${teamDisplayCode(credential.teamCode)} · Member ${credential.teamSlot}\nEmail: ${credential.email}\nPassword: ${credential.password}`).join("\n\n")}</pre><div className="confirm-modal-actions"><button type="button" className="outline-action" onClick={()=>setTeamCredentials(null)}>CLOSE</button></div></section></div>}
  {tab==="overview"&&<section className="admin-content"><div className="metric-grid"><Metric label="REGISTERED TEAMS" value={teams.length}/><Metric label="TEAM MEMBERS" value={teams.reduce((sum,t)=>sum+t.users.length,0)}/><Metric label="PUBLISHED POWER CARDS" value={cards.filter(x=>x.published).length}/><Metric label="PUBLISHED PROBLEMS" value={problems.filter(x=>x.published).length}/></div><div className="admin-panel event-control-panel"><div><span className="section-index">EVENT STATUS</span><h2>{event?.name??"Algorithm Auction"}</h2><p>Event status: <b>{event?.status??"DRAFT"}</b> · Coding round: <b>{event?.codingRoundOpen?"OPEN":"LOCKED"}</b></p></div><div className="inline-actions"><button className="outline-action" disabled={busy} onClick={()=>askConfirmation("Start the event?","The event will become live, with the coding round still locked.","START EVENT",()=>request("/api/admin/event","PATCH",{status:"LIVE",codingRoundOpen:false}))}>START EVENT</button><button className="primary-button compact" disabled={busy} onClick={()=>askConfirmation("Open the coding round?","Opening the coding round converts each active team’s remaining credits into score bonus points using the configured rate. Settle or cancel outstanding online bids first. Teams will then be able to open assigned algorithms and submit code.","OPEN ROUND",()=>request("/api/admin/event","PATCH",{status:"LIVE",codingRoundOpen:true}))}>OPEN CODING ROUND ↗</button></div></div><div className="admin-panel"><div className="panel-title"><div><span className="section-index">LIVE OVERVIEW</span><h2>Teams</h2></div><button className="outline-action" onClick={()=>setTab("teams")}>MANAGE TEAMS ↗</button></div><TeamTable teams={teams.slice(0,8)} onlineMembers={onlineMembers} onDeduct={(teamId,body)=>request(`/api/admin/teams/${teamId}/credits/deduct`,"POST",body)} onConfirm={askConfirmation}/></div></section>}
  {tab==="teams"&&<section className="admin-content admin-two-col"><CreateTeam onCreate={body=>request("/api/admin/teams","POST",body)} onConfirm={askConfirmation}/><div className="admin-panel"><div className="panel-title"><div><span className="section-index">TEAM ROSTER</span><h2>{teams.length} teams</h2></div><div className="inline-actions"><button className="outline-action" disabled={busy||!teams.length} onClick={()=>askConfirmation("Reset team login credentials?","All team member email addresses and passwords will be changed to the Team A–Z pattern. Team members will be signed out. Administrator logins will not change. The new credentials will be shown once after confirmation.","UPDATE LOGINS",async()=>{const result=await request("/api/admin/team-credentials/reset","POST",{confirmation:"RESET TEAM LOGIN CREDENTIALS"},false);if(result?.credentials)setTeamCredentials(result.credentials);return result;},true)}>RESET TEAM LOGINS</button></div></div><TeamTable teams={teams} onlineMembers={onlineMembers} onDeduct={(teamId,body)=>request(`/api/admin/teams/${teamId}/credits/deduct`,"POST",body)} onConfirm={askConfirmation}/><AllocationPanel teams={teams} cards={cards.filter(card=>card.published)} problems={problems.filter(problem=>problem.published)} onSave={(teamId,body)=>request(`/api/admin/teams/${teamId}/allocations`,"PUT",body)} onAssign={(teamId,problemId)=>request(`/api/admin/teams/${teamId}/allocations/problems`,"POST",{problemId})} onUnassign={(teamId,problemId)=>request(`/api/admin/teams/${teamId}/allocations/problems/${problemId}`,"DELETE")} onConfirm={askConfirmation} onNotify={setMessage}/><TeamTimingPanel teams={teams} onExtend={(teamId,sessionId,extraSeconds)=>request(`/api/admin/teams/${teamId}/coding-sessions/${sessionId}/extend`,"POST",{extraSeconds})} onConfirm={askConfirmation}/></div></section>}
 {tab==="cards"&&<section className="admin-content admin-two-col"><CreateCard key={editingCard?.id??"new-card"} card={editingCard??undefined} onCancel={()=>setEditingCard(null)} onConfirm={askConfirmation} onSave={async body=>{const result=await request(editingCard?`/api/admin/power-cards/${editingCard.id}`:"/api/admin/power-cards",editingCard?"PUT":"POST",body);if(result)setEditingCard(null);return result;}}/><div className="admin-panel"><div className="panel-title"><div><span className="section-index">CARD CATALOG</span><h2>Published and draft cards</h2></div></div>{cards.map(card=><div className="catalog-row" key={card.id}>{card.imageUrl&&<img className="admin-card-thumbnail" src={`${api}${card.imageUrl}`} alt=""/>}<div><b>{card.name}</b><p>{card.description}</p><small>VERSION {card.version} · {card.startingBid} CR · {card.effectType} {card.effectValue||""}</small></div><div className="catalog-actions"><span className={card.published?"published-pill":"draft-pill"}>{card.published?"PUBLISHED":"DRAFT"}</span><button className="outline-action small" disabled={busy} onClick={()=>setEditingCard(card)}>{card.published?"CREATE REVISION":"EDIT"}</button><button className={displayCardId===card.id?"primary-button compact":"outline-action small"} disabled={busy||!card.published} onClick={()=>void request("/api/admin/display","PUT",{kind:"POWER_CARD",itemId:displayCardId===card.id?null:card.id})}>{displayCardId===card.id?"STOP DISPLAY":"DISPLAY FOR TEAMS"}</button>{card.published?<button className="danger-action small" disabled={busy} onClick={()=>askConfirmation("Unpublish power card?",`Unpublish ${card.name} now? Any live auction listing will close and held bid credits will be released. Existing team copies remain usable.`,"UNPUBLISH",()=>request(`/api/admin/power-cards/${card.id}/unpublish`),true)}>UNPUBLISH</button>:<button className="outline-action small" disabled={busy} onClick={()=>askConfirmation("Publish power card?",`Publish ${card.name} for the event?`,"PUBLISH",()=>request(`/api/admin/power-cards/${card.id}/publish`))}>PUBLISH</button>}<button className="danger-action small" disabled={busy} onClick={()=>askConfirmation("Permanently delete power card?",`This permanently deletes ${card.name}, its team copies and activation records, and all related auction items and bids. Spent auction credits are refunded. Effects already applied to scores, credits, or timers are not reversed.`,"DELETE PERMANENTLY",()=>request(`/api/admin/power-cards/${card.id}`,"DELETE"),true)}>DELETE</button></div></div>)}{!cards.length&&<Empty>Power card catalog is empty.</Empty>}</div></section>}
 {tab==="problems"&&<section className="admin-content admin-two-col"><CreateProblem key={editingProblem?.id??"new-problem"} problem={editingProblem??undefined} onCancel={()=>setEditingProblem(null)} onConfirm={askConfirmation} onSave={async body=>{const result=await request(editingProblem?`/api/admin/problems/${editingProblem.id}`:"/api/admin/problems",editingProblem?"PUT":"POST",body);if(result)setEditingProblem(null);return result;}}/><div className="admin-panel"><div className="panel-title"><div><span className="section-index">PROBLEM LIBRARY</span><h2>Algorithm problems</h2></div></div>{problems.map(problem=><div className="catalog-row" key={problem.id}><div><b>{problem.problemCode} · {problem.title}</b><p>{Math.floor(problem.timeLimitSeconds/60)} MIN · {problem.testCases.length} TEST CASES</p><small>VERSION {problem.version}</small></div><div className="catalog-actions"><span className={problem.published?"published-pill":"draft-pill"}>{problem.published?"PUBLISHED":"DRAFT"}</span><button className="outline-action small" disabled={busy} onClick={()=>setEditingProblem(problem)}>{problem.published?"CREATE REVISION":"EDIT"}</button><button className={displayProblemId===problem.id?"primary-button compact":"outline-action small"} disabled={busy||!problem.published} onClick={()=>void request("/api/admin/display","PUT",{kind:"PROBLEM",itemId:displayProblemId===problem.id?null:problem.id})}>{displayProblemId===problem.id?"STOP DISPLAY":"DISPLAY FOR TEAMS"}</button><button className="danger-action small" disabled={busy} onClick={()=>askConfirmation("Reset algorithm code history?",`This clears saved collaborative code, coding timers, submissions, and results for ${problem.problemCode} · ${problem.title} across all teams. The algorithm assignments stay in place, each assigned team’s attempt and score for this algorithm reset, and teams can start again with the full time limit. Teams currently editing will be returned to My Allotments. Running evaluations must finish first. This cannot be undone.`,"RESET CODE HISTORY",()=>request(`/api/admin/problems/${problem.id}/reset-code-history`),true)}>RESET CODE HISTORY</button>{problem.published?<button className="danger-action small" disabled={busy} onClick={()=>askConfirmation("Unpublish algorithm?",`Unpublish ${problem.problemCode} · ${problem.title} now? This removes it from team assignments, ends its active coding timers, and closes any live auction listing. Existing code and submission history will be retained.`,"UNPUBLISH",()=>request(`/api/admin/problems/${problem.id}/unpublish`),true)}>UNPUBLISH</button>:<button className="outline-action small" disabled={busy} onClick={()=>askConfirmation("Publish algorithm?",`Publish ${problem.problemCode} · ${problem.title} for the event?`,"PUBLISH",()=>request(`/api/admin/problems/${problem.id}/publish`))}>PUBLISH</button>}<button className="danger-action small" disabled={busy} onClick={()=>askConfirmation("Permanently delete algorithm?",`This permanently deletes ${problem.problemCode} · ${problem.title}, including team assignments, coding sessions, saved code, submissions, test results, and auction bids. Team scores are recalculated and spent auction credits are refunded.`,"DELETE PERMANENTLY",()=>request(`/api/admin/problems/${problem.id}`,"DELETE"),true)}>DELETE</button></div></div>)}{!problems.length&&<Empty>Problem library is empty.</Empty>}</div></section>}
 {tab==="auctions"&&<section className="admin-content admin-two-col"><CreateAuction cards={cards.filter(card=>card.published)} problems={problems.filter(problem=>problem.published)} onCreate={body=>request("/api/admin/auctions","POST",body)} onConfirm={askConfirmation}/><div className="admin-panel"><div className="panel-title"><div><span className="section-index">AUCTION CONTROL</span><h2>{auctions.length} auctions</h2></div></div>{auctions.map(auction=><div className="auction-admin-row" key={auction.id}><div className="auction-admin-heading"><div><span className="section-index">{auction.kind.replace("_"," ")} · {auction.status}</span><p>Closes {auction.endsAt?new Date(auction.endsAt).toLocaleString():"—"}</p></div><div className="inline-actions">{auction.status==="SCHEDULED"&&<button className="outline-action small" disabled={busy} onClick={()=>askConfirmation("Open auction?",`Open this ${auction.kind.replace("_"," ").toLowerCase()} auction for bidding?`,"OPEN AUCTION",()=>request(`/api/admin/auctions/${auction.id}/open`))}>OPEN</button>}{auction.status==="OPEN"&&<button className="danger-action small" disabled={busy} onClick={()=>askConfirmation("Close auction now?","Bidding will stop and the auction will be settled.","CLOSE AUCTION",()=>request(`/api/admin/auctions/${auction.id}/close`),true)}>CLOSE NOW</button>}</div></div>{auction.items.map(item=><div className="auction-admin-item" key={item.id}><span>{item.problem?.problemCode??item.card?.name??"Catalog item"}</span><b>{item.highestTeam?teamDisplayCode(item.highestTeam.teamCode,item.highestTeam.name):"NO BID"}</b><strong>{item.currentBid} CR</strong><small>{item.status}</small></div>)}</div>)}{!auctions.length&&<Empty>No auctions created yet.</Empty>}</div></section>}
 {tab==="scores"&&<section className="admin-content"><ScoreManager teams={teams} onAdjust={(teamId,body)=>request(`/api/admin/teams/${teamId}/score-adjustments`,"POST",body)} onReset={body=>request("/api/admin/scores/reset","POST",body)} onResetCredits={()=>request("/api/admin/credits/reset","POST",{confirmation:"RESET ALL TEAM CREDITS"})} onConfirm={askConfirmation}/></section>}
 {tab==="event"&&<section className="admin-content"><div className="admin-panel event-control-panel"><div><span className="section-index">EVENT LIFECYCLE</span><h2>Control access to each round.</h2><p>Keep the coding round locked until auctions and allocations are ready.</p></div><div className="event-buttons"><button className="outline-action" disabled={busy} onClick={()=>askConfirmation("Set event ready?","This sets the event to ready and keeps the coding round closed.","SET READY",()=>request("/api/admin/event","PATCH",{status:"READY",codingRoundOpen:false}))}>SET READY</button><button className="outline-action" disabled={busy} onClick={()=>askConfirmation("Start event?","The event becomes live, with coding access still closed.","START EVENT",()=>request("/api/admin/event","PATCH",{status:"LIVE",codingRoundOpen:false}))}>START EVENT</button><button className="primary-button compact" disabled={busy} onClick={()=>askConfirmation("Open coding round?","Opening the coding round converts each active team’s remaining credits into score bonus points using the configured rate. Settle or cancel outstanding online bids first. Teams can then work on their assigned algorithms.","OPEN ROUND",()=>request("/api/admin/event","PATCH",{status:"LIVE",codingRoundOpen:true}))}>OPEN CODING ROUND</button><button className="outline-action" disabled={busy} onClick={()=>askConfirmation("Pause event?","The event and coding access will be paused.","PAUSE EVENT",()=>request("/api/admin/event","PATCH",{status:"PAUSED",codingRoundOpen:false}),true)}>PAUSE EVENT</button><button className="danger-action" disabled={busy} onClick={()=>askConfirmation("End event?","Ending the event closes coding access. This action affects all teams.","END EVENT",()=>request("/api/admin/event","PATCH",{status:"ENDED",codingRoundOpen:false}),true)}>END EVENT</button></div></div><div className="admin-panel visibility-panel"><div><span className="section-index">PUBLIC LEADERBOARD</span><h2>Visibility: {event?.leaderboardVisibility??"HIDDEN"}</h2></div><div className="inline-actions">{(["HIDDEN","PUBLIC","FINAL"] as const).map(value=><button key={value} className={event?.leaderboardVisibility===value?"primary-button compact":"outline-action"} onClick={()=>askConfirmation(`Set leaderboard ${value.toLowerCase()}?`,`Change leaderboard visibility to ${value.toLowerCase()}?`,"CONFIRM",()=>request("/api/admin/event","PATCH",{leaderboardVisibility:value}))}>{value}</button>)}</div></div></section>}
 </section></main>;
}

function tabLabel(tab:Tab){return({overview:"Overview",teams:"Teams management",cards:"Power card management",problems:"Algorithm management",auctions:"Auction management",scores:"Score management",event:"Event controls"})[tab];}
function Metric({label,value}:{label:string;value:number}){return <div className="metric-card"><span>{label}</span><strong>{value.toLocaleString()}</strong><i>↗</i></div>}
function Empty({children}:{children:React.ReactNode}){return <div className="admin-empty">{children}</div>}
function TeamTable({teams,onlineMembers,onDeduct,onConfirm}:{teams:Team[];onlineMembers:Record<string,string[]>;onDeduct:(teamId:string,body:unknown)=>Promise<unknown>;onConfirm:ConfirmAdminAction}){const [editing,setEditing]=useState<Team|null>(null);const [amount,setAmount]=useState("");const [reason,setReason]=useState("");function close(){setEditing(null);setAmount("");setReason("");}function submit(e:FormEvent){e.preventDefault();if(!editing)return;const spent=Number(amount);const team=editing;const note=reason.trim();close();onConfirm("Record physical auction spend?",`Deduct ${spent.toLocaleString()} credits from ${teamDisplayName(team.teamCode,team.name)} for ${note}. Remaining available balance: ${(team.credits-team.reservedCredits-spent).toLocaleString()} credits.` ,"DEDUCT CREDITS",()=>onDeduct(team.id,{amount:spent,reason:note}),true);}return <><div className="team-table-wrap"><table className="team-table"><thead><tr><th>TEAM</th><th>MEMBERS</th><th>PRESENCE</th><th>CREDITS</th><th>SCORE</th><th>ACCESS</th><th>PHYSICAL AUCTION</th></tr></thead><tbody>{teams.map(team=>{const connected=onlineMembers[team.id]??[];const available=team.credits-team.reservedCredits;return <tr key={team.id}><td><b>{teamDisplayName(team.teamCode,team.name)}</b></td><td><div className="team-member-presence">{team.users.map(member=><span key={member.id}><i className={connected.includes(member.id)?"online":""}/>{member.email}</span>)}</div></td><td><span className={connected.length?"published-pill":"draft-pill"}>{connected.length?"ONLINE":"OFFLINE"}</span></td><td>{available.toLocaleString()}</td><td>{team.score?.total??0}</td><td><span className={team.active?"published-pill":"draft-pill"}>{team.active?"ENABLED":"PAUSED"}</span></td><td><button type="button" className="outline-action small" disabled={available<=0} onClick={()=>{setEditing(team);setAmount("");setReason("");}}>RECORD SPEND</button></td></tr>;})}</tbody></table>{!teams.length&&<Empty>No teams have been registered.</Empty>}</div>{editing&&<div className="confirm-modal-backdrop"><form className="confirm-modal" onSubmit={submit}><span className="section-index">PHYSICAL AUCTION</span><h2>Deduct credits for {teamDisplayCode(editing.teamCode,editing.name)}</h2><p>Enter the winning bid amount. The team will then be ready for you to allocate the power card or algorithm they won.</p><div className="admin-field credit-deduction-field"><span>CREDITS SPENT · { (editing.credits-editing.reservedCredits).toLocaleString()} AVAILABLE</span><input type="number" min="1" max={editing.credits-editing.reservedCredits} step="1" required value={amount} onChange={e=>setAmount(e.target.value)}/></div><div className="admin-field credit-deduction-field"><span>WON ITEM OR REASON</span><input required minLength={3} maxLength={200} value={reason} onChange={e=>setReason(e.target.value)} placeholder="e.g. Algorithm 101"/></div><div className="confirm-modal-actions"><button type="submit" className="primary-button compact" disabled={!Number.isInteger(Number(amount))||Number(amount)<1||Number(amount)>editing.credits-editing.reservedCredits||reason.trim().length<3}>REVIEW DEDUCTION</button><button type="button" className="outline-action" onClick={close}>CLOSE</button></div></form></div>}</>}
function CreateTeam({onCreate,onConfirm}:{onCreate:(data:unknown)=>Promise<unknown>;onConfirm:ConfirmAdminAction}){const [form,setForm]=useState({teamCode:"",name:"",email1:"",password1:"",email2:"",password2:""});const change=(key:keyof typeof form)=>(e:React.ChangeEvent<HTMLInputElement>)=>setForm({...form,[key]:e.target.value});async function submit(e:FormEvent){e.preventDefault();onConfirm("Create team?",`Create team ${form.teamCode} · ${form.name} with its two team member accounts?`,"CREATE TEAM",async()=>{const result=await onCreate({teamCode:form.teamCode,name:form.name,members:[{email:form.email1,password:form.password1},{email:form.email2,password:form.password2}]});if(result)setForm({teamCode:"",name:"",email1:"",password1:"",email2:"",password2:""});return result;});}return <form className="admin-panel admin-form" onSubmit={submit}><span className="section-index">REGISTER TEAM</span><h2>Two members. One account.</h2><Field label="TEAM CODE"><input required maxLength={32} value={form.teamCode} onChange={change("teamCode")} placeholder="ALPHA-01"/></Field><Field label="TEAM NAME"><input required maxLength={100} value={form.name} onChange={change("name")} placeholder="Team name"/></Field><div className="form-subhead">MEMBER ONE</div><Field label="MEMBER EMAIL"><input type="email" required value={form.email1} onChange={change("email1")}/></Field><Field label="INITIAL PASSWORD · 12+ CHARACTERS"><input type="password" minLength={12} required value={form.password1} onChange={change("password1")}/></Field><div className="form-subhead">MEMBER TWO</div><Field label="MEMBER EMAIL"><input type="email" required value={form.email2} onChange={change("email2")}/></Field><Field label="INITIAL PASSWORD · 12+ CHARACTERS"><input type="password" minLength={12} required value={form.password2} onChange={change("password2")}/></Field><button className="primary-button" type="submit">CREATE TEAM <b>↗</b></button></form>}
function CreateCard({card,onSave,onCancel,onConfirm}:{card?:Card;onSave:(data:unknown)=>Promise<unknown>;onCancel:()=>void;onConfirm:ConfirmAdminAction}){
 const [name,setName]=useState(card?.name??"");const [description,setDescription]=useState(card?.description??"");const [benefits,setBenefits]=useState(card?.benefits.join("\n")??"");const [conditions,setConditions]=useState(card?.conditions??"");const [bid,setBid]=useState(String(card?.startingBid??0));const [usageLimit,setUsageLimit]=useState(card?.usageLimit?String(card.usageLimit):"");const [effectType,setEffectType]=useState(card?.effectType??"NONE");const [effectValue,setEffectValue]=useState(String(card?.effectValue??0));
 const [imageData,setImageData]=useState<string|null>(null);const [imageChanged,setImageChanged]=useState(false);const [preview,setPreview]=useState<string|null>(card?.imageUrl?`${api}${card.imageUrl}`:null);const [imageError,setImageError]=useState("");
 function chooseImage(file?:File){setImageError("");if(!file)return;if(!["image/png","image/jpeg","image/webp"].includes(file.type)){setImageError("Choose a PNG, JPEG, or WebP image.");return;}if(file.size>1_500_000){setImageError("Image must be 1.5 MB or smaller.");return;}const reader=new FileReader();reader.onload=()=>{const data=String(reader.result);setImageData(data);setPreview(data);setImageChanged(true);};reader.onerror=()=>setImageError("Could not read this image.");reader.readAsDataURL(file);}
 function removeImage(){setImageData(null);setPreview(null);setImageChanged(true);setImageError("");}
 async function submit(e:FormEvent){e.preventDefault();onConfirm(card?"Save power card configuration?":"Create power card draft?",card?`Save the revised configuration for ${card.name}?`:`Create a draft power card named ${name}?`,card?"SAVE CHANGES":"CREATE DRAFT",async()=>{const payload={name,description,benefits:benefits.split("\n").map(x=>x.trim()).filter(Boolean),conditions:conditions||null,usageLimit:usageLimit?Number(usageLimit):null,effectType,effectValue:Number(effectValue),startingBid:Number(bid),...(imageChanged?{imageData}: {})};const result=await onSave(payload);if(result&&!card){setName("");setDescription("");setBenefits("");setConditions("");setBid("0");setUsageLimit("");setEffectType("NONE");setEffectValue("0");setImageData(null);setImageChanged(false);setPreview(null);}return result;});}
 return <form className="admin-panel admin-form" onSubmit={submit}><span className="section-index">{card?`CONFIGURE POWER CARD · VERSION ${card.version}`:"NEW POWER CARD"}</span><h2>{card?"Edit the card configuration.":"Create a card draft."}</h2>{card?.published&&<p className="form-hint">Saving creates a new draft version. The published version stays in use until you publish the replacement.</p>}<Field label="CARD NAME"><input required maxLength={100} value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="DESCRIPTION"><textarea required maxLength={10000} rows={4} value={description} onChange={e=>setDescription(e.target.value)}/></Field><Field label="CARD IMAGE · PNG, JPEG, OR WEBP · MAX 1.5 MB"><input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>chooseImage(e.target.files?.[0])}/></Field>{preview&&<div className="card-image-preview"><img src={preview} alt="Power card preview"/><button type="button" className="danger-action small" onClick={removeImage}>REMOVE IMAGE</button></div>}{imageError&&<p className="error-banner">{imageError}</p>}<Field label="BENEFITS · ONE PER LINE"><textarea rows={4} value={benefits} onChange={e=>setBenefits(e.target.value)}/></Field><Field label="SPECIAL CONDITIONS"><textarea rows={3} value={conditions} onChange={e=>setConditions(e.target.value)}/></Field><div className="admin-form-row"><Field label="STARTING BID"><input type="number" min="0" value={bid} onChange={e=>setBid(e.target.value)}/></Field><Field label="USAGE LIMIT · EMPTY IS UNLIMITED"><input type="number" min="1" value={usageLimit} onChange={e=>setUsageLimit(e.target.value)}/></Field></div><Field label="ACTIVATION EFFECT"><select value={effectType} onChange={e=>setEffectType(e.target.value)}><option value="NONE">Description only</option><option value="TIME_EXTENSION">Extend active problem timer</option><option value="CREDIT_GRANT">Grant team credits</option><option value="SCORE_BONUS">Add score points</option></select></Field>{effectType!=="NONE"&&<Field label={effectType==="TIME_EXTENSION"?"EXTENSION · SECONDS":"EFFECT VALUE · POINTS OR CREDITS"}><input type="number" min="1" value={effectValue} onChange={e=>setEffectValue(e.target.value)}/></Field>}<button className="primary-button" disabled={!name.trim()||!description.trim()||Boolean(imageError)}> {card?"SAVE CARD CONFIGURATION":"SAVE POWER CARD DRAFT"} <b>↗</b></button>{card&&<button type="button" className="outline-action" onClick={onCancel}>CANCEL EDITING</button>}<p className="form-hint">Effects are applied by the server when a team activates the card.</p></form>
}
function CreateProblem({problem,onSave,onCancel,onConfirm}:{problem?:Problem;onSave:(data:unknown)=>Promise<unknown>;onCancel:()=>void;onConfirm:ConfirmAdminAction}){
 const [code,setCode]=useState(problem?.problemCode??"");const [title,setTitle]=useState(problem?.title??"");const difficulty=problem?.difficulty??"EASY";const [statement,setStatement]=useState(problem?.statement??"");const [inputFormat,setInputFormat]=useState(problem?.inputFormat??"");const [outputFormat,setOutputFormat]=useState(problem?.outputFormat??"");const [constraints,setConstraints]=useState(problem?.constraints??"");const [limit,setLimit]=useState(String(problem?.timeLimitSeconds??1200));const [score,setScore]=useState(String(problem?.maxScore??100));const [startingBid,setStartingBid]=useState(String(problem?.startingBid??0));const [maxBid,setMaxBid]=useState(problem?.maxBid===null||problem?.maxBid===undefined?"":String(problem.maxBid));
 const [cases,setCases]=useState(()=>problem?problem.testCases.map(({input,expected,weight,isSample})=>({input,expected,weight,isSample})):[{input:"",expected:"",weight:0,isSample:true},{input:"",expected:"",weight:100,isSample:false}]);
 const maxScore=Number(score);const weightTotal=cases.filter(test=>!test.isSample).reduce((sum,test)=>sum+Number(test.weight),0);const samples=cases.filter(test=>test.isSample);
 function updateCase(index:number,key:"input"|"expected"|"weight"|"isSample",value:string|boolean|number){setCases(current=>current.map((test,i)=>i===index?{...test,[key]:value}:test));}
 async function submit(e:FormEvent){e.preventDefault();const testCases=cases.map((test,position)=>({...test,position}));onConfirm(problem?"Save algorithm configuration?":"Create algorithm draft?",problem?`Save configuration changes for ${problem.problemCode} · ${problem.title}?`:`Create a draft algorithm ${code} · ${title}?`,problem?"SAVE CHANGES":"CREATE DRAFT",async()=>{const result=await onSave({problemCode:code,title,difficulty,statement,inputFormat,outputFormat,constraints,sampleExamples:samples.map(test=>({input:test.input,output:test.expected})),startingBid:Number(startingBid),maxBid:maxBid?Number(maxBid):null,timeLimitSeconds:Number(limit),maxScore,testCases});if(result&&!problem){setCode("");setTitle("");setStatement("");setCases([{input:"",expected:"",weight:0,isSample:true},{input:"",expected:"",weight:maxScore,isSample:false}]);}return result;});}
 return <form className="admin-panel admin-form" onSubmit={submit}><span className="section-index">{problem?`CONFIGURE ALGORITHM · VERSION ${problem.version}`:"NEW ALGORITHM"}</span><h2>{problem?"Edit the algorithm configuration.":"Create a problem draft."}</h2>{problem?.published&&<p className="form-hint">Saving creates a new draft version. The published version stays in use until you publish the replacement.</p>}<Field label="PROBLEM ID"><input required value={code} onChange={e=>setCode(e.target.value)}/></Field><Field label="TITLE"><input required value={title} onChange={e=>setTitle(e.target.value)}/></Field><Field label="PROBLEM STATEMENT"><textarea required rows={7} value={statement} onChange={e=>setStatement(e.target.value)}/></Field><Field label="INPUT FORMAT"><textarea required rows={3} value={inputFormat} onChange={e=>setInputFormat(e.target.value)}/></Field><Field label="OUTPUT FORMAT"><textarea required rows={3} value={outputFormat} onChange={e=>setOutputFormat(e.target.value)}/></Field><div className="admin-form-row"><Field label="TIME LIMIT · SECONDS"><input type="number" min="60" value={limit} onChange={e=>setLimit(e.target.value)}/></Field><Field label="MAX SCORE"><input type="number" min="1" value={score} onChange={e=>{const next=e.target.value;setScore(next);setCases(current=>{const hidden=current.filter(test=>!test.isSample);if(hidden.length===1)return current.map(test=>test.isSample?test:{...test,weight:Number(next)});return current;});}}/></Field></div><p className="form-hint">Fully accepted solutions earn 0.5 timing points for each complete 10 seconds remaining.</p><Field label="STARTING BID"><input type="number" min="0" value={startingBid} onChange={e=>setStartingBid(e.target.value)}/></Field><Field label="MAXIMUM BID · OPTIONAL"><input type="number" min={startingBid} value={maxBid} onChange={e=>setMaxBid(e.target.value)}/></Field><div className="form-subhead">TEST CASES · HIDDEN INPUTS NEVER REACH TEAMS</div>{cases.map((test,index)=><div className="test-case-form" key={index}><div className="test-case-title"><span>CASE {String(index+1).padStart(2,"0")}</span><label><input type="checkbox" checked={test.isSample} onChange={e=>updateCase(index,"isSample",e.target.checked)}/> SAMPLE</label><button type="button" disabled={cases.length<=2} onClick={()=>setCases(current=>current.filter((_,i)=>i!==index))}>REMOVE</button></div><Field label="INPUT"><textarea rows={3} value={test.input} onChange={e=>updateCase(index,"input",e.target.value)}/></Field><Field label="EXPECTED OUTPUT"><textarea rows={2} value={test.expected} onChange={e=>updateCase(index,"expected",e.target.value)}/></Field>{!test.isSample&&<Field label="WEIGHT"><input type="number" min="0" value={test.weight} onChange={e=>updateCase(index,"weight",Number(e.target.value))}/></Field>}</div>)}<button className="outline-action" type="button" onClick={()=>setCases(current=>[...current,{input:"",expected:"",weight:0,isSample:false}])}>ADD TEST CASE +</button><p className={`weight-summary ${weightTotal===maxScore?"valid":"invalid"}`}>OFFICIAL WEIGHT {weightTotal} / {maxScore} POINTS · {samples.length} SAMPLE(S)</p><button className="primary-button" disabled={!samples.length||!cases.some(test=>!test.isSample)||weightTotal!==maxScore||!code.trim()||!title.trim()}>{problem?"SAVE ALGORITHM CONFIGURATION":"SAVE PROBLEM DRAFT"} <b>↗</b></button>{problem&&<button type="button" className="outline-action" onClick={onCancel}>CANCEL EDITING</button>}</form>
}function TeamTimingPanel({teams,onExtend,onConfirm}:{teams:Team[];onExtend:(teamId:string,sessionId:string,extraSeconds:number)=>Promise<unknown>;onConfirm:ConfirmAdminAction}){
 const [teamId,setTeamId]=useState(teams[0]?.id??"");const [sessionId,setSessionId]=useState("");const [extraMinutes,setExtraMinutes]=useState("5");const [sessions,setSessions]=useState<{id:string;startedAt:string;deadlineAt:string;remainingSeconds:number;problem:{problemCode:string;title:string}}[]>([]);const [loading,setLoading]=useState(false);const [saving,setSaving]=useState(false);const [message,setMessage]=useState("");
 useEffect(()=>{if(!teams.some(team=>team.id===teamId))setTeamId(teams[0]?.id??"");},[teams,teamId]);
 const load=useCallback(async()=>{if(!teamId){setSessions([]);return;}setLoading(true);try{const response=await fetch(`${api}/api/admin/teams/${teamId}/coding-sessions`,{credentials:"include"});const data=await response.json();if(!response.ok)throw new Error(data.error??"Could not load active algorithm sessions");const active=data.sessions??[];setMessage("");setSessions(active);setSessionId(current=>active.some((session:{id:string})=>session.id===current)?current:active[0]?.id??"");}catch(error){setMessage(error instanceof Error?error.message:"Could not load active algorithm sessions");setSessions([]);setSessionId("");}finally{setLoading(false);}},[teamId]);
 useEffect(()=>{void load();},[load,teams]);
  async function submit(event:FormEvent){event.preventDefault();const minutes=Number(extraMinutes);if(!teamId||!sessionId||!Number.isInteger(minutes)||minutes<1||minutes>120)return;onConfirm("Extend this team’s timer?",`Add ${minutes} minute${minutes===1?"":"s"} to the selected team’s active algorithm. Both teammates will receive the new deadline.`,"ADD TIME",async()=>{setSaving(true);try{const result=await onExtend(teamId,sessionId,minutes*60);if(result)await load();return result;}finally{setSaving(false);}});}
  return <form className="admin-panel admin-form team-timing-panel" onSubmit={submit}><span className="section-index">TEAM TIMER CONTROL</span><h2>Extend an active algorithm.</h2><p className="form-hint">Adds time to one team’s active session and updates both teammates’ editors immediately.</p>{message&&<p className="error-banner" role="alert">{message}</p>}<Field label="TEAM"><select required value={teamId} onChange={event=>setTeamId(event.target.value)}>{teams.map(team=><option key={team.id} value={team.id}>{teamDisplayName(team.teamCode,team.name)}</option>)}</select></Field><Field label="ACTIVE ALGORITHM"><select required disabled={loading||!sessions.length} value={sessionId} onChange={event=>setSessionId(event.target.value)}><option value="">{loading?"CHECKING SESSIONS…":sessions.length?"Choose an active algorithm":"No active algorithm for this team"}</option>{sessions.map(session=><option key={session.id} value={session.id}>{session.problem.problemCode} · {session.problem.title} · {Math.floor(session.remainingSeconds/60)}:{String(session.remainingSeconds%60).padStart(2,"0")} left</option>)}</select></Field><div className="admin-form-row"><Field label="ADD MINUTES · 1–120"><input type="number" min="1" max="120" step="1" required value={extraMinutes} onChange={event=>setExtraMinutes(event.target.value)}/></Field><div className="team-timing-current">{loading?"CHECKING SESSIONS…":sessions.length?"ACTIVE SESSION":"NO ACTIVE SESSION"}</div></div><button className="primary-button" disabled={saving||loading||!sessionId||Number(extraMinutes)<1||Number(extraMinutes)>120}>{saving?"UPDATING TIMER…":"ADD TIME TO SESSION"} <b>↗</b></button>{!loading&&teamId&&!sessions.length&&<p className="form-hint">Select the team whose member has opened an assigned algorithm. Its timer will appear here.</p>}</form>
}function AllocationPanel({teams,cards,problems,onSave,onAssign,onUnassign,onConfirm,onNotify}:{teams:Team[];cards:Card[];problems:Problem[];onSave:(teamId:string,data:unknown)=>Promise<unknown>;onAssign:(teamId:string,problemId:string)=>Promise<unknown>;onUnassign:(teamId:string,problemId:string)=>Promise<unknown>;onConfirm:ConfirmAdminAction;onNotify:(message:string)=>void}){
 const [teamId,setTeamId]=useState(teams[0]?.id??"");const [cardIds,setCardIds]=useState<string[]>([]);const [problemToAssign,setProblemToAssign]=useState("");const [assigned,setAssigned]=useState<{id:string;problemCode:string;title:string;status:string}[]>([]);const [loadingAssignments,setLoadingAssignments]=useState(false);const [savingCards,setSavingCards]=useState(false);const [assigning,setAssigning]=useState(false);const [removingId,setRemovingId]=useState("");const [pendingRemoval,setPendingRemoval]=useState<{id:string;problemCode:string;title:string}|null>(null);
 useEffect(()=>{if(!teams.some(team=>team.id===teamId))setTeamId(teams[0]?.id??"");},[teams,teamId]);
 const loadAssignments=useCallback(async()=>{if(!teamId){setAssigned([]);setCardIds([]);return;}setLoadingAssignments(true);try{const response=await fetch(`${api}/api/admin/teams/${teamId}/allocations`,{credentials:"include"});const data=await response.json();if(!response.ok)throw new Error(data.error??"Could not load team allocations");setAssigned(data.problems??[]);setCardIds((data.powerCards??[]).map((card:{id:string})=>card.id));setProblemToAssign("");}catch{setAssigned([]);setCardIds([]);}finally{setLoadingAssignments(false);}},[teamId]);
 useEffect(()=>{void loadAssignments();},[loadAssignments]);
 async function saveCards(e:FormEvent){e.preventDefault();onConfirm("Save power card allocation?","This replaces the selected team’s power card allotment and leaves its algorithm assignments unchanged.","SAVE POWER CARDS",async()=>{setSavingCards(true);try{const result=await onSave(teamId,{powerCardIds:cardIds});if(result)await loadAssignments();return result;}finally{setSavingCards(false);}});}
 function assignOne(e:FormEvent){e.preventDefault();if(!problemToAssign||assigned.length>=2)return;const problem=problems.find(item=>item.id===problemToAssign);if(!problem)return;onConfirm("Assign one algorithm?",`Assign ${problem.problemCode} · ${problem.title} to this team? ${assigned.length+1} of 2 algorithm slots will be used.`,"ASSIGN ALGORITHM",async()=>{setAssigning(true);try{const result=await onAssign(teamId,problemToAssign);if(result)await loadAssignments();return result;}finally{setAssigning(false);}});}
 async function unassign(){if(!pendingRemoval)return;setRemovingId(pendingRemoval.id);const result=await onUnassign(teamId,pendingRemoval.id);if(result){setPendingRemoval(null);await loadAssignments();}setRemovingId("");}
 const availableProblems=problems.filter(problem=>!assigned.some(item=>item.id===problem.id));
 return <div className="allocation-panel"><div className="form-subhead">TEAM ALLOCATION</div><Field label="TEAM"><select required value={teamId} onChange={e=>setTeamId(e.target.value)}>{teams.map(team=><option key={team.id} value={team.id}>{teamDisplayName(team.teamCode,team.name)}</option>)}</select></Field>
  <div className="assigned-problems"><div className="form-subhead">CURRENT ALGORITHMS · {assigned.length}/2</div>{assigned.map(problem=><div className="assigned-problem-row" key={problem.id}><span><b>{problem.problemCode} · {problem.title}</b><small>{problem.status.replaceAll("_"," ")}</small></span><button type="button" className="danger-action small" disabled={removingId===problem.id||problem.status==="IN_PROGRESS"} title={problem.status==="IN_PROGRESS"?"Wait for the team’s active coding session to finish":"Unassign this algorithm; prior coding history will be preserved"} onClick={()=>setPendingRemoval(problem)}>{removingId===problem.id?"REMOVING…":"UNASSIGN"}</button></div>)}{!loadingAssignments&&!assigned.length&&<p className="form-hint">No algorithms are assigned to this team.</p>}{loadingAssignments&&<p className="form-hint">Loading assignments…</p>}</div>
  <form onSubmit={assignOne}><Field label={`ASSIGN ONE ALGORITHM · ${assigned.length}/2 SLOTS USED`}><select required value={problemToAssign} disabled={loadingAssignments||assigning||assigned.length>=2||!availableProblems.length} onChange={e=>setProblemToAssign(e.target.value)}><option value="">{assigned.length>=2?"Maximum of two algorithms reached":availableProblems.length?"Choose one published algorithm":"No more published algorithms available"}</option>{availableProblems.map(problem=><option key={problem.id} value={problem.id}>{problem.problemCode} · {problem.title}</option>)}</select></Field><button className="outline-action" disabled={!teamId||!problemToAssign||assigning||assigned.length>=2}>{assigning?"ASSIGNING…":"ASSIGN SELECTED ALGORITHM ↗"}</button></form>
  <form onSubmit={saveCards}><Field label="POWER CARDS · MULTISELECT"><select multiple size={Math.min(5,Math.max(3,cards.length))} value={cardIds} onChange={e=>setCardIds(Array.from(e.currentTarget.selectedOptions,option=>option.value))}>{cards.map(card=><option key={card.id} value={card.id}>{card.name}</option>)}</select></Field><button className="outline-action" disabled={!teamId||savingCards}>{savingCards?"SAVING…":"SAVE POWER CARD ALLOTMENT ↗"}</button></form>
  {pendingRemoval&&<div className="confirm-modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget&&!removingId)setPendingRemoval(null);}}><section className="confirm-modal" role="dialog" aria-modal="true" aria-labelledby="unassign-title"><span className="section-index">REMOVE TEAM ALGORITHM</span><h2 id="unassign-title">Unassign this algorithm?</h2><p><b>{pendingRemoval.problemCode} · {pendingRemoval.title}</b> will be removed from the team’s active algorithm list. Existing code, submissions, and assignment history will be preserved.</p><div className="confirm-modal-actions"><button type="button" className="danger-action" onClick={()=>void unassign()} disabled={!!removingId}>{removingId?"REMOVING…":"REMOVE"}</button><button type="button" className="outline-action" onClick={()=>setPendingRemoval(null)} disabled={!!removingId}>CLOSE</button></div></section></div>}
 </div>
}function ScoreManager({teams,onAdjust,onReset,onResetCredits,onConfirm}:{teams:Team[];onAdjust:(teamId:string,data:unknown)=>Promise<unknown>;onReset:(data:unknown)=>Promise<unknown>;onResetCredits:()=>Promise<unknown>;onConfirm:ConfirmAdminAction}){
 const [teamId,setTeamId]=useState(teams[0]?.id??"");const [delta,setDelta]=useState("0");const [reason,setReason]=useState("");const [resetConfirmation,setResetConfirmation]=useState("");const [history,setHistory]=useState<{oldValue:number;newValue:number;reason:string;createdAt:string;actor:{email:string}}[]>([]);const selected=teams.find(team=>team.id===teamId);
 const load=useCallback(async()=>{if(!teamId)return;const response=await fetch(`${api}/api/admin/teams/${teamId}/score-adjustments`,{credentials:"include"});if(response.ok)setHistory((await response.json()).score);},[teamId]);
 useEffect(()=>{load();},[load]);
 async function submit(e:FormEvent){e.preventDefault();onConfirm("Apply score adjustment?",`Apply ${Number(delta)>0?"+":""}${delta} points to ${selected?teamDisplayName(selected.teamCode,selected.name):"the selected team"}?`,"APPLY ADJUSTMENT",async()=>{const result=await onAdjust(teamId,{delta:Number(delta),reason});if(result){setDelta("0");setReason("");await load();}return result;});}
 async function resetScores(e:FormEvent){e.preventDefault();if(resetConfirmation!=="RESET ALL SCORES")return;onConfirm("Reset the entire scoreboard?",`This resets every team’s score to zero for ${teams.length} teams and deletes the manual score adjustment history shown here. If the coding round is open, it will be closed as part of this reset. Code and submission history are kept. Wait for queued or running evaluations to finish first. This cannot be undone.`,"RESET ALL SCORES",async()=>{const result=await onReset({confirmation:resetConfirmation});if(result)setResetConfirmation("");return result;},true);}
 return <div className="score-manager"><form className="admin-panel admin-form" onSubmit={submit}><span className="section-index">MANUAL ADJUSTMENT</span><h2>Correct a team score.</h2><Field label="TEAM"><select value={teamId} onChange={e=>setTeamId(e.target.value)}>{teams.map(team=><option value={team.id} key={team.id}>{teamDisplayName(team.teamCode,team.name)} · {team.score?.total??0} PTS</option>)}</select></Field><Field label="POINTS · USE A NEGATIVE VALUE TO DEDUCT"><input type="number" step="1" value={delta} onChange={e=>setDelta(e.target.value)}/></Field><Field label="REASON · REQUIRED FOR AUDIT"><textarea minLength={5} maxLength={500} required rows={4} value={reason} onChange={e=>setReason(e.target.value)}/></Field><button className="primary-button" disabled={!teamId||Number(delta)===0}>SAVE SCORE CORRECTION <b>↗</b></button><p className="form-hint">Every adjustment stores the admin, timestamp, old value, new value, and reason.</p></form><div className="admin-panel"><div className="panel-title"><div><span className="section-index">SCORE HISTORY</span><h2>{selected?teamDisplayName(selected.teamCode,selected.name):"Choose a team"} · {selected?.score?.total??0} PTS</h2></div></div>{history.map(entry=><div className="score-history-row" key={entry.createdAt}><div><b>{entry.oldValue} → {entry.newValue}</b><p>{entry.reason}</p><small>{entry.actor.email} · {new Date(entry.createdAt).toLocaleString()}</small></div><strong>{entry.newValue-entry.oldValue>0?"+":""}{entry.newValue-entry.oldValue}</strong></div>)}{!history.length&&<Empty>No manual adjustments recorded for this team.</Empty>}<form className="score-reset-box" onSubmit={resetScores}><span className="section-index">RESET SCOREBOARD</span><h3>Reset all teams to zero.</h3><p className="form-hint">Clears all manual score adjustment history and resets every team to zero. Code and submission history are kept; older submissions won’t count toward scores again. Close the coding round and let running evaluations finish first.</p><Field label={'TYPE "RESET ALL SCORES" TO CONFIRM'}><input required value={resetConfirmation} onChange={e=>setResetConfirmation(e.target.value)} autoComplete="off"/></Field><button type="submit" className="danger-action" disabled={resetConfirmation!=="RESET ALL SCORES"}>RESET ALL TEAM SCORES</button></form><div className="score-reset-box"><span className="section-index">RESET TEAM CREDITS</span><h3>Restore all teams’ starting credits.</h3><p className="form-hint">This overwrites every team’s current credit balance, including physical auction deductions, and recalculates credit bonuses. Close or settle auctions with active bids first.</p><button type="button" className="danger-action" disabled={!teams.length} onClick={()=>onConfirm("Reset all team credits?","Every team will be reset to the event’s configured starting balance. Current balances and physical auction deductions will be overwritten, and credit bonuses will be recalculated. This cannot be undone.","RESET ALL CREDITS",onResetCredits,true)}>RESET ALL CREDITS</button></div></div></div>
}
function CreateAuction({cards,problems,onCreate,onConfirm}:{cards:Card[];problems:Problem[];onCreate:(data:unknown)=>Promise<unknown>;onConfirm:ConfirmAdminAction}){
 const [kind,setKind]=useState("POWER_CARD");const [itemIds,setItemIds]=useState<string[]>([]);const [end,setEnd]=useState(()=>{const d=new Date(Date.now()+30*60_000);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16);});
 const entries=kind==="POWER_CARD"?cards.map(card=>({id:card.id,label:card.name})):problems.map(problem=>({id:problem.id,label:`${problem.problemCode} · ${problem.title}`}));
 async function submit(e:FormEvent){e.preventDefault();onConfirm("Create scheduled auction?",`Create a ${kind.replace("_"," ").toLowerCase()} auction with ${itemIds.length} selected item${itemIds.length===1?"":"s"}?`,"CREATE AUCTION",async()=>{const result=await onCreate({kind,itemIds,endsAt:new Date(end).toISOString()});if(result)setItemIds([]);return result;});}
 return <form className="admin-panel admin-form" onSubmit={submit}><span className="section-index">CREATE AUCTION</span><h2>Set the bidding window.</h2><Field label="AUCTION TYPE"><select value={kind} onChange={e=>{setKind(e.target.value);setItemIds([]);}}><option value="POWER_CARD">Power card auction</option><option value="PROBLEM">Algorithm auction</option></select></Field><Field label="PUBLISHED ITEMS · SELECT MULTIPLE"><select multiple size={Math.min(7,Math.max(3,entries.length))} value={itemIds} onChange={e=>setItemIds(Array.from(e.currentTarget.selectedOptions,option=>option.value))}>{entries.map(entry=><option key={entry.id} value={entry.id}>{entry.label}</option>)}</select></Field><Field label="CLOSES AT"><input type="datetime-local" required value={end} onChange={e=>setEnd(e.target.value)}/></Field><button className="primary-button" disabled={!itemIds.length}>CREATE SCHEDULED AUCTION <b>↗</b></button><p className="form-hint">Create the auction, then use OPEN to start accepting bids. Timed auctions settle automatically when they close.</p></form>
}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="admin-field"><span>{label}</span>{children}</label>}
